CREATE TRIGGER IF NOT EXISTS trg_free_fields_fts_insert
AFTER INSERT ON free_fields FOR EACH ROW WHEN NEW.fts_indexed = 1 AND NEW.status = 'active'
BEGIN
INSERT INTO search_index (entity_type, entity_id, title, body)
  SELECT 'free_field', CAST(NEW.id AS TEXT), NEW.key, NEW.value
  WHERE NEW.fts_indexed = 1 AND NEW.status = 'active';
END;

CREATE TRIGGER IF NOT EXISTS trg_free_fields_fts_update
AFTER UPDATE ON free_fields FOR EACH ROW
